# Test: Network Blocking Fixture
# ---------------------------------------------------------------------------
class TestNetworkBlocking:
    """Verify the autouse fixture blocks all network I/O."""

    def test_socket_creation_blocked(self, pytester):
        """Attempting to create a socket should raise RuntimeError."""
        pytester.makepyfile(
            """
            import socket
            import pytest

            def test_network_blocked():
                with pytest.raises(RuntimeError, match="Network I/O is forbidden"):
                    socket.socket()
            """
        )
        result = pytester.runpytest()
        result.assert_outcomes(passed=1)

    def test_create_connection_blocked(self, pytester):
        """Attempting to create a connection should raise RuntimeError."""
        pytester.makepyfile(
            """
            import socket
            import pytest

            def test_connection_blocked():
                with pytest.raises(RuntimeError, match="Network I/O is forbidden"):
                    socket.create_connection(("example.com", 80))
            """
        )
        result = pytester.runpytest()
        result.assert_outcomes(passed=1)

    def test_gethostbyname_blocked(self, pytester):
        """DNS resolution should raise RuntimeError."""
        pytester.makepyfile(
            """
            import socket
            import pytest

            def test_dns_blocked():
                with pytest.raises(RuntimeError, match="Network I/O is forbidden"):
                    socket.gethostbyname("example.com")
            """
        )
        result = pytester.runpytest()
        result.assert_outcomes(passed=1)

    def test_network_block_applies_to_all_tests(self, pytester):
        """The autouse fixture must apply to every test in the session."""
        pytester.makepyfile(
            """
            import socket
            import pytest

            def test_one():
                with pytest.raises(RuntimeError):
                    socket.socket()

            def test_two():
                with pytest.raises(RuntimeError):
                    socket.create_connection(("localhost", 1))
            """
        )
        result = pytester.runpytest()
        result.assert_outcomes(passed=2)


