# Test: Timing Guard Hook
# ---------------------------------------------------------------------------
class TestTimingGuard:
    """Verify the pytest_runtest_call hook enforces the 500ms limit."""

    def test_fast_test_passes(self, pytester):
        """A test completing under 500ms should pass normally."""
        pytester.makepyfile(
            """
            def test_fast():
                assert True
            """
        )
        start_time = time.monotonic()
        result = pytester.runpytest()
        elapsed = time.monotonic() - start_time
        result.assert_outcomes(passed=1)
        assert elapsed < 5.0  # Sanity check: suite itself is fast

    def test_slow_test_fails(self, pytester):
        """A test exceeding 500ms should be marked as failed."""
        pytester.makepyfile(
            """
            import time

            def test_slow():
                time.sleep(0.6)  # Exceed the 500ms threshold
                assert True
            """
        )
        result = pytester.runpytest()
        result.assert_outcomes(failed=1)
        result.stdout.fnmatch_lines(["*exceeds 500ms*"])

    def test_timing_hook_does_not_break_normal_execution(self, pytester):
        """The hook should not interfere with normal test setup/teardown."""
        pytester.makepyfile(
            """
            import pytest

            @pytest.fixture
            def resource():
                return [1, 2, 3]

            def test_with_fixture(resource):
                assert len(resource) == 3
            """
        )
        result = pytester.runpytest()
        result.assert_outcomes(passed=1)


