# ---------------------------------------------------------------------------
# Test: Subprocess-Level Validation (True Isolation)
# ---------------------------------------------------------------------------
class TestSubprocessIsolation:
    """
    Run pytest in a subprocess to validate the conftest behaves correctly
    without interference from the parent test session's fixtures.
    """

    def _run_pytest_in_subprocess(self, test_code: str, tmp_path) -> subprocess.CompletedProcess:
        """Helper to execute a pytest run in a clean subprocess."""
        test_file = tmp_path / "test_isolated.py"
        test_file.write_text(textwrap.dedent(test_code))

        # Create a minimal conftest in the same directory to ensure it's loaded
        conftest_file = tmp_path / "conftest.py"
        conftest_file.write_text(
            textwrap.dedent(
                """
                import pytest
                import socket

                def pytest_configure(config):
                    config.addinivalue_line("markers", "tier0: Tier 0 smoke tests")

                @pytest.fixture(autouse=True)
                def _enforce_no_network(monkeypatch):
                    def _blocked(*args, **kwargs):
                        raise RuntimeError("Network I/O is forbidden in Tier 0 smoke tests.")
                    monkeypatch.setattr(socket, "socket", _blocked)
                    monkeypatch.setattr(socket, "create_connection", _blocked)
                    monkeypatch.setattr(socket, "gethostbyname", _blocked)

                @pytest.hookimpl(hookwrapper=True)
                def pytest_runtest_call(item):
                    import time
                    start = time.monotonic()
                    outcome = yield
                    elapsed = time.monotonic() - start
                    if elapsed > 0.5:
                        raise RuntimeError(f"Test {item.name} exceeds 500ms ({elapsed:.3f}s)")
                """
            )
        )

        result = subprocess.run(
            [sys.executable, "-m", "pytest", str(test_file), "-v", "--tb=short"],
            capture_output=True,
            text=True,
            cwd=str(tmp_path),
            timeout=30,
        )
        return result

    def test_network_block_in_subprocess(self, tmp_path):
        """Verify network blocking works in a fully isolated environment."""
        test_code = """
            import socket
            import pytest

            def test_blocked():
                with pytest.raises(RuntimeError, match="Network I/O is forbidden"):
                    socket.socket()
        """
        result = self._run_pytest_in_subprocess(test_code, tmp_path)
        assert result.returncode == 0, f"Subprocess pytest failed:\n{result.stdout}\n{result.stderr}"

    def test_timing_guard_in_subprocess(self, tmp_path):
        """Verify the timing guard triggers in a fully isolated environment."""
        test_code = """
            import time

            def test_slow():
                time.sleep(0.6)
                assert True
        """
        result = self._run_pytest_in_subprocess(test_code, tmp_path)
        assert result.returncode != 0, "Slow test should have failed"
        assert "exceeds 500ms" in result.stdout

    def test_fast_test_in_subprocess(self, tmp_path):
        """Verify fast tests pass in a fully isolated environment."""
        test_code = """
            def test_fast():
                assert True
        """
        result = self._run_pytest_in_subprocess(test_code, tmp_path)
        assert result.returncode == 0, f"Subprocess pytest failed:\n{result.stdout}\n{result.stderr}"


